import{_ as a,C as r,c as o,o as n,a3 as t,G as i}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"Point of Sale","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/point-of-sale/index.md","filePath":"master/sales/point-of-sale/index.md","lastUpdated":1792041590000}'),d={name:"master/sales/point-of-sale/index.md"};function l(h,e,p,u,c,g){const s=r("ImagePopup");return n(),o("div",null,[e[0]||(e[0]=t('<h1 id="point-of-sale" tabindex="-1">Point of Sale <a class="header-anchor" href="#point-of-sale" aria-label="Permalink to &quot;Point of Sale&quot;">​</a></h1><p>Point of Sale (POS) is the module you use at the till. It lets a cashier ring up a sale, take payment, print a receipt and close the day with a cash count. Every sale feeds your stock and your accounts, so the shop and the back office always agree. Use it for a retail shop, a café or a full restaurant with tables.</p><blockquote><p><strong>In simple words:</strong> POS is your cash register. You set it up once, open it each day, sell, and close it at night.</p></blockquote><h2 id="words-used-in-this-guide" tabindex="-1">Words used in this guide <a class="header-anchor" href="#words-used-in-this-guide" aria-label="Permalink to &quot;Words used in this guide&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Word</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Point of Sale (POS)</strong></td><td>The module as a whole.</td></tr><tr><td><strong>Register</strong></td><td>One till, with its own rules. Also called a terminal.</td></tr><tr><td><strong>Session</strong></td><td>One shift of selling on a register.</td></tr><tr><td><strong>Cashier terminal</strong></td><td>The till screen where the cashier sells.</td></tr></tbody></table><p>Amounts in this guide have no currency sign. They use the register currency.</p><h2 id="the-two-parts-of-pos" tabindex="-1">The two parts of POS <a class="header-anchor" href="#the-two-parts-of-pos" aria-label="Permalink to &quot;The two parts of POS&quot;">​</a></h2><p>POS has two screens that work together.</p><ul><li><strong>The admin app.</strong> Open the <strong>Point of Sale</strong> app from the main menu. Here you set up registers, payment methods, floors and prices. You also watch sessions, orders, payments and reports.</li><li><strong>The cashier terminal.</strong> This is the till screen. It has its own pages: <strong>Registers</strong>, <strong>Home</strong> and <strong>Orders</strong>. Cashiers add products, pick customers, take payments and print receipts here.</li></ul><p>You open the terminal from the admin <strong>Dashboard</strong>. Click <strong>Open Register</strong> on a closed register, or <strong>Continue Selling</strong> on an open one.</p>',10)),i(s,{src:"/images1/pos/pos_dashboard_registers.png",alt:"Point of Sale dashboard showing the Spice Route Kitchen & Bar and TechNest Electronics register cards with their session status and the Continue Selling button"}),e[1]||(e[1]=t('<h2 id="the-full-flow" tabindex="-1">The full flow <a class="header-anchor" href="#the-full-flow" aria-label="Permalink to &quot;The full flow&quot;">​</a></h2><p>Follow these stages in order. Each one has its own page.</p><ol><li><strong>Set up a register.</strong> First create payment methods and coins and bills, and make your products available. See <a href="./payments-setup/">Payments setup</a> and <a href="./products-pricing/">Products and pricing</a>. Then create the register, choose its payment methods, journals, prices and receipt text. See <a href="./get-started/set-up-a-register.html">Set up a register</a>.</li><li><strong>Open a session.</strong> A session is one shift of selling. Count the cash in the drawer and start. See <a href="./sessions/open-register.html">Open a register</a>.</li><li><strong>Sell.</strong> Add products to an order, pick a customer, add notes. In a restaurant, start from a table. See <a href="./selling/take-an-order.html">Take an order</a>.</li><li><strong>Pay and print the receipt.</strong> Choose a payment method, enter the amount and validate. See <a href="./selling/pay-and-receipt.html">Pay and receipt</a>.</li><li><strong>Refund or invoice.</strong> Return products from a paid order, or create a customer invoice for it. See <a href="./selling/refunds.html">Refunds</a> and <a href="./selling/invoice-a-pos-order.html">Invoice a POS order</a>.</li><li><strong>Move cash in or out.</strong> Record money put into or taken out of the drawer during the shift. See <a href="./sessions/cash-in-and-out.html">Cash in and out</a>.</li><li><strong>Close the session.</strong> Count the cash, compare it with the expected balance and post the entries. See <a href="./sessions/close-session.html">Close a session</a>.</li><li><strong>Check reports.</strong> Review orders, sales details and sessions. See <a href="./reporting/">Reporting</a>.</li></ol><h2 id="what-the-groups-contain" tabindex="-1">What the groups contain <a class="header-anchor" href="#what-the-groups-contain" aria-label="Permalink to &quot;What the groups contain&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Group</th><th>What you find there</th></tr></thead><tbody><tr><td><a href="./get-started/">Get started</a></td><td>Tour of the module, register set-up, module settings</td></tr><tr><td><a href="./sessions/">Sessions</a></td><td>Open, cash in and out, close</td></tr><tr><td><a href="./selling/">Selling</a></td><td>The terminal, orders, tables, payment, refunds, invoices</td></tr><tr><td><a href="./orders-payments/">Orders and payments</a></td><td>Admin lists of orders, payments and customers</td></tr><tr><td><a href="./products-pricing/">Products and pricing</a></td><td>Products, POS categories, attributes, prices and taxes</td></tr><tr><td><a href="./payments-setup/">Payments setup</a></td><td>Payment methods, coins and bills, preparation printers</td></tr><tr><td><a href="./reporting/">Reporting</a></td><td>Dashboard and the three reports</td></tr></tbody></table><h2 id="example-used-in-this-guide" tabindex="-1">Example used in this guide <a class="header-anchor" href="#example-used-in-this-guide" aria-label="Permalink to &quot;Example used in this guide&quot;">​</a></h2><p>The pages use two sample shops.</p><ul><li><strong>TechNest Electronics</strong> (short code TNE) is a retail shop. It sells items such as the Glide Wireless Mouse and BudsAir Wireless Earbuds to customers like Sofia Rossi and Tom Baker.</li><li><strong>Spice Route Kitchen &amp; Bar</strong> (short code SRK) is a restaurant. It has two floors, Ground Floor and Rooftop Lounge, with tables T1 to T8.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>New to POS? Read <a href="./get-started/pos-overview.html">POS overview</a> first, then <a href="./get-started/set-up-a-register.html">Set up a register</a>.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../../finance/customer-invoices/">Customer invoices</a></li><li><a href="./../sales/quotations-orders/">Sales orders and quotations</a></li><li><a href="./../../getting-started/contacts/contacts.html">Contacts</a></li></ul>',11))])}const S=a(d,[["render",l]]);export{f as __pageData,S as default};
